('time-hop-mass','Time Hop, Mass','psychoportation',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','All willing creatures in range',NULL,NULL,'Up to 1 hour/level; see text',NULL,NULL,'no',NULL,15,'Send any number of willing creatures in range forward through time for a chosen number of hours up to your manifester level.','Spend 6 additional PP to manifest as an immediate action.'),
('time-regression','Time Regression','psychoportation',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'Instantaneous',NULL,NULL,'no',NULL,17,'Regress time to just before your previous turn, replaying the intervening round while only you retain memory of the first version.','XP cost: 1,000 XP.'),
